require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_login();if(!user_has_any_permission($user,['ACLARACION_CREAR','ACLARACION_GESTIONAR']))json_response(['ok'=>false,'error'=>'Sin permiso'],403);$in=json_input();$id=(int)($in['aclaracion_id']??0);$message=trim((string)($in['mensaje']??''));if($id<=0||$message==='')json_response(['ok'=>false,'error'=>'Escribe un mensaje'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$st=$db->prepare("SELECT a.aclaracion_id,a.estatus,pm.* FROM movimiento_aclaracion a JOIN presupuesto_movimiento pm ON pm.movimiento_id=a.movimiento_id WHERE a.aclaracion_id=?");$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();$st->close();if(!$row||!movement_is_visible($db,$user,$row)){$db->close();json_response(['ok'=>false,'error'=>'Aclaración no encontrada'],404);}if($row['estatus']==='CERRADA'){$db->close();json_response(['ok'=>false,'error'=>'La aclaración está cerrada'],409);}$uid=(int)$user['user_id'];$internal=(int)($in['es_interno']??0)===1&&user_has_permission($user,'ACLARACION_GESTIONAR')?1:0;$st=$db->prepare("INSERT INTO movimiento_aclaracion_mensaje(aclaracion_id,usuario_id,mensaje,es_interno) VALUES(?,?,?,?)");$st->bind_param('iisi',$id,$uid,$message,$internal);$st->execute();$mid=(int)$st->insert_id;$st->close();$db->query("UPDATE movimiento_aclaracion SET updated_at=NOW(),estatus=IF(estatus='ABIERTA','EN_REVISION',estatus) WHERE aclaracion_id=".(int)$id);audit_log($db,$uid,'ACLARACION_MENSAJE','ACLARACION',$id,'Mensaje agregado',null,['mensaje_id'=>$mid]);$db->close();json_response(['ok'=>true,'data'=>['mensaje_id'=>$mid]]);
